def histogram(test):
    # Split the input string into individual letters and count their occurrences
    letter_counts = {letter: test.count(letter) for letter in test}

    # Sort the dictionary based on the number of occurrences in descending order
    sorted_histogram = dict(sorted(letter_counts.items(), key=lambda item: item[1], reverse=True))

    return sorted_histogram

# Example usage:
print(histogram('a b c'))  # Output: {'a': 1, 'b': 1, 'c': 1}
print(histogram('a b b a'))  # Output: {'a': 2, 'b': 2}
print(histogram('a b c a b'))  # Output: {'a': 2, 'b': 2}
print(histogram('b b b b a'))  # Output: {'b': 4}
print(histogram(''))  # Output: {}
```

