def exchange(lst1, lst2):
    # Check if there are no even numbers in lst1 or they are already all even
    if not any(x % 2 == 0 for x in lst1) or len([x for x in lst1 if x % 2 != 0]) > len(lst1):
        return "NO"

    # Check if there are no odd numbers in lst2 or they are already all even
    elif not any(x % 2 == 1 for x in lst2) or len([x for x in lst2 if x % 2 != 0]) > len(lst2):
        return "NO"

    # Check if there is at least one element in lst1 that can be exchanged with an odd number in lst2
    for i, num in enumerate(lst1):
        for j, num2 in enumerate(lst2):
            if num % 2 == 0 and num2 % 2 != 0:
                return "YES"

    return "NO"

# Test cases
print(exchange([1, 2, 3, 4], [1, 2, 3, 4]))  # Output: "YES"
print(exchange([1, 2, 3, 4], [1, 5, 3, 4]))  # Output: "NO"
