        return n == n[::-1]

    def count_changes(arr):
        changes = 0
        for i in range(len(arr) // 2):
            if arr[i] != arr[~i]:
                changes += 1
        return changes

    def find_smallest_change(arr):
        n = len(arr)
        while not is_palindrome(arr):
            arr = count_changes(arr)
            changes += 1
        return changes

    return find_smallest_change(arr)

