def tri(n):
    if n == 0 or n == 1 or n == 2:
        return [n]
    else:
        trib_sequence = [1, 3]
        for i in range(3, n + 1):
            if i % 2 == 0:
                trib_sequence.append(trib_sequence[i - 1] + trib_sequence[i // 2])
            else:
                trib_sequence.append(trib_sequence[i - 1] + trib_sequence[i - 2] + trib_sequence[i])
        return trib_sequence

# Example usage
print(tri(3))  # Output: [1, 3, 2, 8]
